//! Installing the addons into WoW, and the "Start with Windows" setting.
//!
//! Unlike the Python helper, the exe no longer copies itself into %LOCALAPPDATA% or registers
//! itself to start with Windows on first run: the setup program (installer/SevenTVEmotesHelper.iss)
//! does that. The tray toggle and --autostart still switch the same Run-key entry on and off.

use crate::library::Library;
use crate::seventv::Http;
use crate::wow::{CORE_ADDON, LOCAL_ADDON, addons_dir};
use std::path::Path;
use std::sync::Arc;

/// The addon folders shipped inside the exe (generated by build.rs from ../addon).
pub mod bundle {
    include!(concat!(env!("OUT_DIR"), "/bundled_addons.rs"));

    pub fn file(addon: &str, rel: &str) -> Option<&'static [u8]> {
        FILES
            .iter()
            .find(|(a, r, _)| *a == addon && *r == rel)
            .map(|(_, _, d)| *d)
    }
}

/// `## Version: 1.2.3` from a TOC file's text.
pub fn toc_version_of(text: &str) -> Vec<u64> {
    for line in text.lines() {
        let Some(rest) = line.strip_prefix("##") else {
            continue;
        };
        let rest = rest.trim_start();
        let Some(v) = rest.strip_prefix("Version:") else {
            continue;
        };
        let v = v.trim_start();
        let num: String = v
            .chars()
            .take_while(|c| c.is_ascii_digit() || *c == '.')
            .collect();
        if num.is_empty() {
            return Vec::new();
        }
        return num
            .split('.')
            .filter(|s| !s.is_empty())
            .map(|s| s.parse().unwrap_or(0))
            .collect();
    }
    Vec::new()
}

pub fn toc_version(toc: &Path) -> Vec<u64> {
    std::fs::read(toc)
        .map(|b| toc_version_of(&String::from_utf8_lossy(&b)))
        .unwrap_or_default()
}

/// Make sure both addons are in this game folder. Returns (library, list of changes made).
pub fn ensure_addons(
    flavor: &Path,
    cache_dir: &Path,
    http: Arc<dyn Http>,
) -> std::io::Result<(Library, Vec<String>)> {
    let mut changes = Vec::new();
    let ad = addons_dir(flavor);
    std::fs::create_dir_all(&ad)?;
    let fname = flavor
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_default();

    let core_dst = ad.join(CORE_ADDON);
    let toc_name = format!("{CORE_ADDON}.toc");
    if let Some(ship_toc) = bundle::file(CORE_ADDON, &toc_name) {
        let have = toc_version(&core_dst.join(&toc_name));
        let ship = toc_version_of(&String::from_utf8_lossy(ship_toc));
        if have.is_empty() || ship > have {
            for (addon, rel, data) in bundle::FILES {
                if *addon != CORE_ADDON {
                    continue;
                }
                let dst = core_dst.join(rel.replace('/', std::path::MAIN_SEPARATOR_STR));
                if let Some(parent) = dst.parent() {
                    std::fs::create_dir_all(parent)?;
                }
                std::fs::write(&dst, data)?;
            }
            changes.push(format!(
                "{} {CORE_ADDON} in {fname}",
                if have.is_empty() {
                    "installed"
                } else {
                    "updated"
                }
            ));
        }
    }

    let template = bundle::file(LOCAL_ADDON, &format!("{LOCAL_ADDON}.toc")).map(|d| d.to_vec());
    let mut lib = Library::new(flavor, cache_dir, template, http);
    if !lib.installed() {
        lib.install()?;
        changes.push(format!("created {LOCAL_ADDON} in {fname}"));
    }
    Ok((lib, changes))
}

// --------------------------------------------------------------------------- autostart

pub const RUN_KEY: &str = "Software\\Microsoft\\Windows\\CurrentVersion\\Run";

/// Command line that starts the helper at login.
pub fn launch_command() -> String {
    let exe = std::env::current_exe()
        .map(|p| p.to_string_lossy().into_owned())
        .unwrap_or_default();
    let exe = crate::wow::resolve(Path::new(&exe))
        .map(|p| p.to_string_lossy().into_owned())
        .unwrap_or(exe);
    format!("\"{exe}\" --background")
}

#[cfg(windows)]
pub fn autostart_enabled() -> bool {
    crate::win::reg_get_user(RUN_KEY, crate::paths::APP_NAME).is_some()
}

#[cfg(windows)]
pub fn set_autostart(enabled: bool) -> std::io::Result<()> {
    if enabled {
        crate::win::reg_set_user(RUN_KEY, crate::paths::APP_NAME, &launch_command())
    } else {
        crate::win::reg_delete_user(RUN_KEY, crate::paths::APP_NAME)
    }
}

#[cfg(not(windows))]
pub fn autostart_enabled() -> bool {
    false
}

#[cfg(not(windows))]
pub fn set_autostart(_enabled: bool) -> std::io::Result<()> {
    log::info!("autostart isn't supported on this platform");
    Ok(())
}

pub fn open_path(p: &Path) {
    #[cfg(windows)]
    crate::win::shell_open(p);
    #[cfg(target_os = "macos")]
    let _ = std::process::Command::new("open").arg(p).spawn();
    #[cfg(all(unix, not(target_os = "macos")))]
    let _ = std::process::Command::new("xdg-open").arg(p).spawn();
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn toc_versions() {
        assert_eq!(
            toc_version_of("## Interface: 1\n## Version: 0.5.0\n"),
            vec![0, 5, 0]
        );
        assert_eq!(toc_version_of("##Version: 2"), vec![2]);
        assert!(toc_version_of("## Title: x").is_empty());
        assert!(vec![0, 5, 1] > vec![0, 5]);
        assert!(bundle::file(CORE_ADDON, "SevenTVEmotes.toc").is_some());
        assert!(bundle::file(LOCAL_ADDON, "SevenTVEmotes_Local.toc").is_some());
    }
}
